class LLMVendor(ABC):
    id: str = "base"
    label: str = "Base"
    capabilities: set[str] = set()

    def __init__(self, config: dict):
        self.config = config

    @abstractmethod
    def chat(self, messages, *, model=None, max_tokens=1024,
             temperature=0.2, tools=None) -> ChatResult: ...

    def embed(self, texts, *, model=None) -> EmbedResult:
        raise NotImplementedError(f"{self.id} does not support embeddings")

    def ping(self) -> tuple[bool, str]:
        try:
            r = self.chat([ChatMessage("user", "ping")], max_tokens=4)
            return True, f"ok ({len(r.text)} chars)"
        except Exception as e:
            return False, str(e)

def reload(self):
    self._vendors.clear()
    for entry in self._settings.get("vendors", []):
        if not entry.get("active"):
            continue
        try:
            mod = importlib.import_module(f"Application.vendors.{entry['module']}")
            cls = getattr(mod, entry["class"])
            self._vendors[entry["id"]] = cls(entry)
            log.info("Loaded vendor %s (%s)", entry["id"], entry["class"])
        except Exception as e:
            log.error("Failed to load vendor %s: %s", entry.get("id"), e)

def pick_chat(self, prefer: str | None = None) -> LLMVendor:
    if prefer and self.registry.is_active(prefer):
        return self.registry.get(prefer)
    d = self.registry.default("chat")
    if d:
        return d
    for v in self.registry.active_with("chat"):
        return v
    raise RuntimeError("No active chat vendor configured")

def chat(self, messages, *, model=None, max_tokens=1024, temperature=0.2, tools=None):
    model = model or self.config.get("default_chat_model", "claude-sonnet-4-6")
    sys = next((m.content for m in messages if m.role == "system"), None)
    msgs = [{"role": m.role, "content": m.content}
            for m in messages if m.role in ("user", "assistant")]
    kwargs = dict(model=model, max_tokens=max_tokens, temperature=temperature, messages=msgs)
    if sys:
        kwargs["system"] = sys
    r = self.client.messages.create(**kwargs)
    text = "".join(b.text for b in r.content if hasattr(b, "text"))
    return ChatResult(text=text, tokens_in=getattr(r.usage, "input_tokens", 0),
                      tokens_out=getattr(r.usage, "output_tokens", 0), model=model, ...)

SYSTEM_PROMPT = (
    "You are CogniBase, a senior OnBase analyst. "
    "Use ONLY the provided context to answer. Cite sources by their id. "
    "If context is insufficient, say so.")

def answer(self, question, *, vendor=None, top_k=8) -> dict:
    hits = self.retriever.search(question, top_k=top_k)
    ctx = "\n\n".join(f"[{h['id']}] {h['text']}" for h in hits)
    chat = self.router.pick_chat(prefer=vendor)
    result = chat.chat([
        ChatMessage("system", SYSTEM_PROMPT),
        ChatMessage("user", f"Context:\n{ctx}\n\nQuestion: {question}")])
    return {"answer": result.text,
            "citations": [{"id": h["id"], "metadata": h["metadata"], "score": h["score"]}
                          for h in hits],
            "vendor_used": f"{chat.id}:{result.model}", ...}

